using Nafadh_Backend.DTOs;
using Nafadh_Backend.Enums;
using Nafadh_Backend.Enums.Nafadh_Backend.Enums;
using Nafadh_Backend.Interfaces;
using Nafadh_Backend.Models;
using Nafadh_Backend.Repositories;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace Nafadh_Backend.Services
{
    public class RemediationService : IRemediationService
    {
        private readonly IRemediationRepository _repository;
        private readonly Nafadhcontext _context;

        public RemediationService(
            IRemediationRepository repository,
            Nafadhcontext context)
        {
            _repository = repository;
            _context = context;
        }

        public async Task<IEnumerable<RemediationRequestDto>> GetAllRequestsAsync(
            string? searchTerm = null,
            int? status = null)
        {
            var requests = await _repository.GetAllWithDetailsAsync(
                searchTerm,
                status);

            return requests.Select(r => new RemediationRequestDto
            {
                RequestId = r.RequestId,
                WarningId = r.WarningId,
                CompanyId = r.CompanyId,

                CompanyName = r.Company != null
                    ? r.Company.CompanyName
                    : "شركة غير محددة",

                OriginalViolationType = r.Warning != null
                    ? r.Warning.Type.ToString()
                    : "-",

                // Retrieve the original warning issue date.
                WarningIssuedDate = r.Warning != null
                    ? r.Warning.IssuedDate
                    : null,

                RequestedAction = r.RequestedAction,
                SubmissionDate = r.SubmissionDate,
                Status = r.Status,
                ReviewNotes = r.ReviewNotes
            }).ToList();
        }

        public async Task<RemediationRequestDto?> GetRequestByIdAsync(int id)
        {
            var r = await _repository.GetByIdWithDetailsAsync(id);

            if (r == null)
                return null;

            return new RemediationRequestDto
            {
                RequestId = r.RequestId,
                WarningId = r.WarningId,
                CompanyId = r.CompanyId,

                CompanyName = r.Company != null
                    ? r.Company.CompanyName
                    : "شركة غير محددة",

                OriginalViolationType = r.Warning != null
                    ? r.Warning.Type.ToString()
                    : "-",

                // Retrieve the original warning issue date.
                WarningIssuedDate = r.Warning != null
                    ? r.Warning.IssuedDate
                    : null,

                RequestedAction = r.RequestedAction,
                SubmissionDate = r.SubmissionDate,
                Status = r.Status,
                ReviewNotes = r.ReviewNotes
            };
        }

        public async Task<RemediationRequestDto> CreateRequestAsync(
            CreateRemediationRequestDto dto)
        {
            var entity = new RemediationRequest
            {
                WarningId = dto.WarningId,
                CompanyId = dto.CompanyId,
                RequestedAction = dto.RequestedAction,
                SubmissionDate = DateTime.UtcNow,
                Status = NFD_RemediationStatus.Pending
            };

            // 1. حفظ طلب المعالجة
            await _repository.AddAsync(entity);

            // 2. إنشاء إشعار لمدير النظام (Admin)
            try
            {
                var adminNotification = new NFD_Notification
                {
                    UserId = 1, // معرّف حساب مدير النظام
                    Title = "طلب معالجة إنذار جديد",
                    Message = $"قامت الشركة بتقديم طلب معالجة للإنذار رقم #{entity.WarningId}.",
                    RelatedEntity = $"RemediationRequest:{entity.RequestId}",
                    CreatedAt = DateTime.UtcNow,
                    IsRead = false
                };

                _context.NFD_Notifications.Add(adminNotification);
                await _context.SaveChangesAsync();
            }
            catch
            {
                // منع أي تعطل في حال حدوث استثناء
            }

            return (await GetRequestByIdAsync(entity.RequestId))!;
        }

        public async Task<bool> ReviewRequestAsync(
            int id,
            ReviewRemediationRequestDto dto)
        {
            var request = await _repository.GetByIdAsync(id);

            if (request == null)
                return false;

            request.Status = dto.Status;
            request.ReviewNotes = dto.ReviewNotes;
            request.ReviewedByUserId = dto.ReviewedByUserId;
            request.ReviewedDate = DateTime.UtcNow;

            await _repository.UpdateAsync(request);

            return true;
        }
    }
}
